<body>
<div class="wrap">
  <header>
    <h1>Search Promise Board</h1>
    <p>Draft SERP-facing promises, score them for specificity, proof strength, and risk, then copy a compact content brief.</p>
  </header>

  <section class="panel">
    <div class="grid two">
      <div>
        <label for="topic">Topic</label>
        <input id="topic" placeholder="Example: Roth conversion mistakes">
      </div>
      <div>
        <label for="audience">Audience</label>
        <input id="audience" placeholder="Example: retirees with taxable income">
      </div>
    </div>
    <div class="actions">
      <button class="primary" id="draftBtn">Draft promise cards</button>
      <button id="addBtn">Add blank card</button>
      <button id="sortBtn">Sort by score</button>
      <button class="warn" id="clearBtn">Clear</button>
    </div>
    <div class="status" id="status"></div>
  </section>

  <section class="panel">
    <div class="meta">
      <div>
        <span class="pill" id="countPill">0 cards</span>
        <span class="pill" id="avgPill">Avg 0</span>
      </div>
      <span class="pill">Risk lowers score</span>
    </div>
    <div id="cards"></div>
  </section>

  <section class="panel">
    <div class="meta">
      <h2 style="font-size:1rem;margin:0;">Concise brief</h2>
      <div class="cardtools">
        <button class="small primary" id="copyBtn">Copy brief</button>
        <button class="small" id="exportBtn">Export .txt</button>
      </div>
    </div>
    <div class="briefbox" id="brief"></div>
  </section>

  <div class="footer">Runs locally. No accounts, APIs, external files, or internet needed.</div>
</div>

<script>
(function(){
  const storeKey = "searchPromiseBoard.v1";
  const $ = (id) => document.getElementById(id);

  let state = {
    topic:"",
    audience:"",
    cards:[]
  };

  function uid(){
    return "c" + Math.random().toString(36).slice(2,10);
  }

  function esc(s){
    return String(s || "").replace(/[&<>"']/g, ch => ({
      "&":"&amp;",
      "<":"&lt;",
      ">":"&gt;",
      '"':"&quot;",
      "'":"&#039;"
    }[ch]));
  }

  function score(card){
    const spec = Number(card.specificity || 1);
    const proof = Number(card.proofScore || 1);
    const risk = Number(card.riskScore || 1);
    return Math.round(((spec * 0.38) + (proof * 0.38) + ((6 - risk) * 0.24)) / 5 * 100);
  }

  function scoreLabel(n){
    if(n >= 82) return "Strong";
    if(n >= 65) return "Usable";
    if(n >= 45) return "Needs work";
    return "Weak";
  }

  function save(){
    state.topic = $("topic").value.trim();
    state.audience = $("audience").value.trim();
    localStorage.setItem(storeKey, JSON.stringify(state));
    buildBrief();
  }

  function load(){
    try{
      const raw = localStorage.getItem(storeKey);
      if(raw) state = JSON.parse(raw);
    }catch(e){}
    $("topic").value = state.topic || "";
    $("audience").value = state.audience || "";
  }

  function setStatus(msg){
    $("status").textContent = msg || "";
    if(msg){
      clearTimeout(setStatus.t);
      setStatus.t = setTimeout(() => $("status").textContent = "", 2200);
    }
  }

  function makeCard(data){
    return Object.assign({
      id:uid(),
      promise:"",
      snippet:"",
      proof:"",
      risk:"",
      notes:"",
      specificity:3,
      proofScore:3,
      riskScore:3
    }, data || {});
  }

  function cleanTopic(){
    return $("topic").value.trim() || "your topic";
  }

  function cleanAudience(){
    return $("audience").value.trim() || "your audience";
  }

  function draftCards(){
    const topic = cleanTopic();
    const audience = cleanAudience();

    state.topic = $("topic").value.trim();
    state.audience = $("audience").value.trim();

    state.cards = [
      makeCard({
        promise:`A practical ${topic} checklist for ${audience}`,
        snippet:`Give searchers a clear first-pass checklist so they can spot the main decisions, common misses, and next action without reading a giant guide.`,
        proof:`Use numbered steps, example scenarios, decision criteria, and a small “when this matters” section.`,
        risk:`Do not imply the checklist replaces professional judgment. Define who it is and is not for.`,
        notes:`Best when the SERP has broad explainers but weak actionability.`,
        specificity:4,
        proofScore:4,
        riskScore:2
      }),
      makeCard({
        promise:`The biggest ${topic} mistakes ${audience} should avoid`,
        snippet:`Position the result around costly or annoying errors, then explain how to recognize and prevent each one.`,
        proof:`Back each mistake with a plain example, consequence, warning sign, and safer alternative.`,
        risk:`Avoid fearmongering. Keep claims proportional and name assumptions clearly.`,
        notes:`Good for high-click intent, but risk control matters.`,
        specificity:4,
        proofScore:3,
        riskScore:3
      }),
      makeCard({
        promise:`How to decide whether ${topic} is worth it for ${audience}`,
        snippet:`Help searchers compare tradeoffs instead of giving a one-size-fits-all answer.`,
        proof:`Include a decision matrix, pros and cons, thresholds, and sample cases.`,
        risk:`Avoid guaranteeing the “right” choice. Show the variables that change the answer.`,
        notes:`Strong for nuanced topics where searchers need confidence.`,
        specificity:5,
        proofScore:4,
        riskScore:3
      }),
      makeCard({
        promise:`${topic} explained simply, with examples for ${audience}`,
        snippet:`Make the page feel approachable while still giving enough detail to act intelligently.`,
        proof:`Use definitions, before/after examples, short FAQs, and a glossary of confusing terms.`,
        risk:`Avoid being too generic. Add audience-specific examples early.`,
        notes:`Useful when the audience is anxious or early in the research journey.`,
        specificity:3,
        proofScore:3,
        riskScore:2
      }),
      makeCard({
        promise:`A proof-backed ${topic} guide for ${audience}`,
        snippet:`Promise a more credible result by showing what the guidance is based on and where uncertainty remains.`,
        proof:`Use citations, screenshots, expert review notes, data points, and clearly labeled assumptions.`,
        risk:`Only use this if the article can actually support the proof promise.`,
        notes:`Highest ceiling when competitors make unsupported claims.`,
        specificity:4,
        proofScore:5,
        riskScore:4
      })
    ];

    render();
    save();
    setStatus("Drafted 5 editable promise cards.");
  }

  function render(){
    const box = $("cards");
    if(!state.cards.length){
      box.innerHTML = `<div class="empty">No cards yet. Add one or draft from your topic and audience.</div>`;
    }else{
      const ranked = [...state.cards].sort((a,b) => score(b) - score(a));
      const topId = ranked[0] ? ranked[0].id : "";
      box.innerHTML = state.cards.map((card, i) => {
        const n = score(card);
        return `
          <article class="card ${card.id === topId ? "top" : ""}" data-id="${card.id}">
            <div class="meta">
              <div>
                <h2>Promise ${i + 1}</h2>
                <span class="pill"><span class="score">${n}</span> ${scoreLabel(n)}</span>
              </div>
              <div class="cardtools">
                <button class="small" data-action="copyCard">Copy</button>
                <button class="small" data-action="dupe">Duplicate</button>
                <button class="small warn" data-action="delete">Delete</button>
              </div>
            </div>

            <div class="fields">
              <div>
                <label>Search-result promise</label>
                <textarea data-field="promise">${esc(card.promise)}</textarea>
              </div>
              <div>
                <label>Snippet angle</label>
                <textarea data-field="snippet">${esc(card.snippet)}</textarea>
              </div>
              <div>
                <label>Proof needed</label>
                <textarea data-field="proof">${esc(card.proof)}</textarea>
              </div>
              <div>
                <label>Risk / claim control</label>
                <textarea data-field="risk">${esc(card.risk)}</textarea>
              </div>
              <div>
                <label>Notes</label>
                <textarea data-field="notes">${esc(card.notes)}</textarea>
              </div>

              <div class="sliders">
                <div class="sliderline">
                  <span>Specificity</span>
                  <input type="range" min="1" max="5" value="${Number(card.specificity || 1)}" data-field="specificity">
                  <output>${Number(card.specificity || 1)}</output>
                </div>
                <div class="sliderline">
                  <span>Proof</span>
                  <input type="range" min="1" max="5" value="${Number(card.proofScore || 1)}" data-field="proofScore">
                  <output>${Number(card.proofScore || 1)}</output>
                </div>
                <div class="sliderline">
                  <span>Risk</span>
                  <input type="range" min="1" max="5" value="${Number(card.riskScore || 1)}" data-field="riskScore">
                  <output>${Number(card.riskScore || 1)}</output>
                </div>
              </div>
            </div>
          </article>
        `;
      }).join("");
    }

    $("countPill").textContent = `${state.cards.length} card${state.cards.length === 1 ? "" : "s"}`;
    const avg = state.cards.length ? Math.round(state.cards.reduce((sum,c) => sum + score(c), 0) / state.cards.length) : 0;
    $("avgPill").textContent = `Avg ${avg}`;
    wireCards();
    buildBrief();
  }

  function wireCards(){
    document.querySelectorAll(".card").forEach(el => {
      const id = el.getAttribute("data-id");
      const card = state.cards.find(c => c.id === id);
      if(!card) return;

      el.querySelectorAll("textarea").forEach(input => {
        input.addEventListener("input", () => {
          card[input.dataset.field] = input.value;
          save();
        });
      });

      el.querySelectorAll('input[type="range"]').forEach(input => {
        input.addEventListener("input", () => {
          card[input.dataset.field] = Number(input.value);
          input.nextElementSibling.textContent = input.value;
          save();
          render();
        });
      });

      el.querySelectorAll("button[data-action]").forEach(btn => {
        btn.addEventListener("click", () => {
          const action = btn.dataset.action;
          if(action === "delete"){
            state.cards = state.cards.filter(c => c.id !== id);
            render();
            save();
          }
          if(action === "dupe"){
            const copy = makeCard(JSON.parse(JSON.stringify(card)));
            copy.id = uid();
            copy.promise = copy.promise + " copy";
            const idx = state.cards.findIndex(c => c.id === id);
            state.cards.splice(idx + 1, 0, copy);
            render();
            save();
          }
          if(action === "copyCard"){
            copyText(cardText(card));
          }
        });
      });
    });
  }

  function cardText(card){
    return [
      `Promise: ${card.promise || ""}`,
      `Score: ${score(card)} (${scoreLabel(score(card))})`,
      `Snippet angle: ${card.snippet || ""}`,
      `Proof needed: ${card.proof || ""}`,
      `Risk control: ${card.risk || ""}`,
      `Notes: ${card.notes || ""}`
    ].join("\n");
  }

  function buildBrief(){
    const topic = $("topic").value.trim() || "Not set";
    const audience = $("audience").value.trim() || "Not set";
    const ranked = [...state.cards].sort((a,b) => score(b) - score(a));
    const top = ranked[0];

    if(!ranked.length){
      $("brief").textContent = "Draft or add cards to generate a concise brief.";
      return "";
    }

    const lines = [];
    lines.push("SEARCH PROMISE BRIEF");
    lines.push("");
    lines.push(`Topic: ${topic}`);
    lines.push(`Audience: ${audience}`);
    lines.push("");

    if(top){
      lines.push("Recommended lead promise");
      lines.push(`${top.promise || "Untitled promise"} — Score ${score(top)}`);
      lines.push(`Snippet angle: ${top.snippet || "Add snippet angle."}`);
      lines.push(`Proof needed: ${top.proof || "Add proof requirement."}`);
      lines.push(`Risk control: ${top.risk || "Add risk control."}`);
      lines.push("");
    }

    lines.push("Ranked promise options");
    ranked.forEach((card, i) => {
      lines.push(`${i + 1}. ${card.promise || "Untitled promise"} — ${score(card)}`);
      if(card.notes) lines.push(`   Note: ${card.notes}`);
    });

    lines.push("");
    lines.push("Use this page to");
    lines.push("1. Match the promise to the real search intent.");
    lines.push("2. Add proof before making strong claims.");
    lines.push("3. Reduce or qualify high-risk wording.");
    lines.push("4. Turn the best promise into title, meta, intro, and outline.");

    const out = lines.join("\n");
    $("brief").textContent = out;
    return out;
  }

  function addBlank(){
    state.cards.unshift(makeCard({
      promise:"New search-result promise",
      snippet:"What the searcher will understand, decide, or do after clicking.",
      proof:"Examples, sources, screenshots, data, expert review, or visible process.",
      risk:"Claims that need qualification, narrowing, or removal.",
      notes:""
    }));
    render();
    save();
  }

  function sortCards(){
    state.cards.sort((a,b) => score(b) - score(a));
    render();
    save();
    setStatus("Sorted by score.");
  }

  function clearAll(){
    if(!confirm("Clear the board?")) return;
    state = { topic:"", audience:"", cards:[] };
    $("topic").value = "";
    $("audience").value = "";
    localStorage.removeItem(storeKey);
    render();
    setStatus("Cleared.");
  }

  async function copyText(text){
    try{
      await navigator.clipboard.writeText(text);
      setStatus("Copied.");
    }catch(e){
      const temp = document.createElement("textarea");
      temp.value = text;
      document.body.appendChild(temp);
      temp.select();
      document.execCommand("copy");
      temp.remove();
      setStatus("Copied.");
    }
  }

  function exportTxt(){
    const text = buildBrief();
    const blob = new Blob([text], {type:"text/plain"});
    const a = document.createElement("a");
    const stamp = new Date().toISOString().slice(0,10);
    a.href = URL.createObjectURL(blob);
    a.download = `search-promise-brief-${stamp}.txt`;
    document.body.appendChild(a);
    a.click();
    URL.revokeObjectURL(a.href);
    a.remove();
  }

  $("draftBtn").addEventListener("click", draftCards);
  $("addBtn").addEventListener("click", addBlank);
  $("sortBtn").addEventListener("click", sortCards);
  $("clearBtn").addEventListener("click", clearAll);
  $("copyBtn").addEventListener("click", () => copyText(buildBrief()));
  $("exportBtn").addEventListener("click", exportTxt);

  ["topic","audience"].forEach(id => {
    $(id).addEventListener("input", save);
  });

  load();
  render();
})();
</script>
</body>
</html>
```

Rebuilt so the card renderer uses `createElement`, `textContent`, and `value`, with no `innerHTML` needed.

