    padding:6px 9px;
    font-size:.78rem;
    font-weight:800;
    white-space:nowrap;
    margin-right:4px;
  }
  .score{
    font-size:1.1rem;
    color:var(--accent);
    font-weight:900;
  }
  .card{
    background:#fff;
    border:1px solid var(--line);
    border-radius:18px;
    padding:12px;
    margin:10px 0;
    box-shadow:0 7px 20px rgba(35,28,18,.06);
  }
  .card.top{
    border-color:rgba(47,111,99,.45);
    box-shadow:0 9px 26px rgba(47,111,99,.10);
  }
  .card h2{
    font-size:1rem;
    margin:0;
    line-height:1.2;
  }
  .cardtools{
    display:flex;
    gap:6px;
    flex-wrap:wrap;
    justify-content:flex-end;
  }
  .fields{
    display:grid;
    gap:9px;
    margin-top:10px;
  }
  .sliders{
    display:grid;
    grid-template-columns:1fr;
    gap:8px;
    background:#faf6ef;
    border:1px solid var(--line);
    border-radius:15px;
    padding:10px;
  }
  .sliderline{
    display:grid;
    grid-template-columns:92px 1fr 28px;
    align-items:center;
    gap:8px;
  }
  .sliderline span:first-child{
    font-size:.78rem;
    font-weight:850;
    color:var(--muted);
  }
  .sliderline output{
    text-align:right;
    font-weight:900;
    color:var(--ink);
  }
  input[type="range"]{
    padding:0;
    border:none;
    box-shadow:none;
    accent-color:var(--accent);
  }
  .briefbox{
    white-space:pre-wrap;
    background:#211f1c;
    color:#fff8ef;
    border-radius:16px;
    padding:12px;
    font-size:.88rem;
    line-height:1.38;
    overflow-wrap:anywhere;
    max-height:360px;
    overflow:auto;
  }
  .empty{
    border:1px dashed var(--line);
    border-radius:16px;
    padding:16px;
    text-align:center;
    color:var(--muted);
    background:#fffaf1;
  }
  .status{
    font-size:.82rem;
    color:var(--muted);
    margin-top:8px;
    min-height:1.2em;
  }
  .footer{
    font-size:.78rem;
    color:var(--muted);
    text-align:center;
    padding:16px 6px;
  }
  @media (min-width:650px){
    .grid.two{grid-template-columns:1fr 1fr}
    .sliders{grid-template-columns:1fr 1fr 1fr}
    .sliderline{grid-template-columns:1fr}
    .sliderline output{text-align:left}
  }
</style>
</head>
<body>
<div class="wrap">
  <header>
    <h1>Search Promise Board</h1>
    <p>Draft SERP-facing promises, score them for specificity, proof strength, and risk, then copy a compact content brief.</p>
  </header>

  <section class="panel">
    <div class="grid two">
      <div>
        <label for="topic">Topic</label>
        <input id="topic" placeholder="Example: Roth conversion mistakes">
      </div>
      <div>
        <label for="audience">Audience</label>
        <input id="audience" placeholder="Example: retirees with taxable income">
      </div>
    </div>
    <div class="actions">
      <button class="primary" id="draftBtn">Draft promise cards</button>
      <button id="addBtn">Add blank card</button>
      <button id="sortBtn">Sort by score</button>
      <button class="warn" id="clearBtn">Clear</button>
    </div>
    <div class="status" id="status"></div>
  </section>

  <section class="panel">
    <div class="meta">
      <div>
        <span class="pill" id="countPill">0 cards</span>
        <span class="pill" id="avgPill">Avg 0</span>
      </div>
      <span class="pill">Risk lowers score</span>
    </div>
    <div id="cards"></div>
  </section>

  <section class="panel">
    <div class="meta">
      <h2 style="font-size:1rem;margin:0;">Concise brief</h2>
      <div class="cardtools">
        <button class="small primary" id="copyBtn">Copy brief</button>
        <button class="small" id="exportBtn">Export .txt</button>
      </div>
    </div>
    <div class="briefbox" id="brief"></div>
  </section>

  <div class="footer">Runs locally. No accounts, APIs, external files, or internet needed.</div>
</div>

<script>
(function(){
  "use strict";

  const storeKey = "searchPromiseBoard.domSafe.v1";
  const root = {
    topic: document.getElementById("topic"),
    audience: document.getElementById("audience"),
    draftBtn: document.getElementById("draftBtn"),
    addBtn: document.getElementById("addBtn"),
    sortBtn: document.getElementById("sortBtn"),
    clearBtn: document.getElementById("clearBtn"),
    copyBtn: document.getElementById("copyBtn"),
    exportBtn: document.getElementById("exportBtn"),
    status: document.getElementById("status"),
    cards: document.getElementById("cards"),
    brief: document.getElementById("brief"),
    countPill: document.getElementById("countPill"),
    avgPill: document.getElementById("avgPill")
  };

  let state = {
    topic: "",
    audience: "",
    cards: []
  };

  function uid(){
    return "c" + Math.random().toString(36).slice(2,10);
  }

  function makeCard(data){
    return Object.assign({
      id: uid(),
      promise: "",
      snippet: "",
      proof: "",
      risk: "",
      notes: "",
      specificity: 3,
      proofScore: 3,
      riskScore: 3
    }, data || {});
  }

  function createEl(tag, opts){
    const node = document.createElement(tag);
    opts = opts || {};

    if(opts.className) node.className = opts.className;
    if(opts.id) node.id = opts.id;
    if(opts.type) node.type = opts.type;
    if(opts.htmlFor) node.htmlFor = opts.htmlFor;
    if(opts.placeholder) node.placeholder = opts.placeholder;
    if(opts.text !== undefined) node.textContent = opts.text;
    if(opts.value !== undefined) node.value = opts.value;
    if(opts.min !== undefined) node.min = opts.min;
    if(opts.max !== undefined) node.max = opts.max;
    if(opts.dataset){
      Object.keys(opts.dataset).forEach(function(key){
        node.dataset[key] = opts.dataset[key];
      });
    }
    if(opts.attrs){
      Object.keys(opts.attrs).forEach(function(key){
        node.setAttribute(key, opts.attrs[key]);
      });
    }

    return node;
  }

  function append(parent){
    for(let i = 1; i < arguments.length; i++){
      const child = arguments[i];
      if(Array.isArray(child)){
        child.forEach(function(item){
          if(item) parent.appendChild(item);
        });
      }else if(child){
        parent.appendChild(child);
      }
    }
    return parent;
  }

  function score(card){
    const spec = Number(card.specificity || 1);
    const proof = Number(card.proofScore || 1);
    const risk = Number(card.riskScore || 1);
    return Math.round(((spec * 0.38) + (proof * 0.38) + ((6 - risk) * 0.24)) / 5 * 100);
  }

  function scoreLabel(n){
    if(n >= 82) return "Strong";
    if(n >= 65) return "Usable";
    if(n >= 45) return "Needs work";
    return "Weak";
  }

  function cleanTopic(){
    return root.topic.value.trim() || "your topic";
  }

  function cleanAudience(){
    return root.audience.value.trim() || "your audience";
  }

  function save(){
    state.topic = root.topic.value.trim();
    state.audience = root.audience.value.trim();
    localStorage.setItem(storeKey, JSON.stringify(state));
    buildBrief();
    updateMetrics();
  }

  function load(){
    try{
      const raw = localStorage.getItem(storeKey);
      if(raw){
        const parsed = JSON.parse(raw);
        if(parsed && typeof parsed === "object"){
          state.topic = parsed.topic || "";
          state.audience = parsed.audience || "";
          state.cards = Array.isArray(parsed.cards) ? parsed.cards.map(makeCard) : [];
        }
      }
    }catch(err){
      state = { topic: "", audience: "", cards: [] };
    }

    root.topic.value = state.topic || "";
    root.audience.value = state.audience || "";
  }

  function setStatus(message){
    root.status.textContent = message || "";
    if(message){
      clearTimeout(setStatus.timer);
      setStatus.timer = setTimeout(function(){
        root.status.textContent = "";
      }, 2200);
    }
  }

  function draftCards(){
    const topic = cleanTopic();
    const audience = cleanAudience();

    state.topic = root.topic.value.trim();
    state.audience = root.audience.value.trim();

    state.cards = [
      makeCard({
        promise: "A practical " + topic + " checklist for " + audience,
        snippet: "Give searchers a clear first-pass checklist so they can spot the main decisions, common misses, and next action without reading a giant guide.",
        proof: "Use numbered steps, example scenarios, decision criteria, and a small “when this matters” section.",
        risk: "Do not imply the checklist replaces professional judgment. Define who it is and is not for.",
        notes: "Best when the SERP has broad explainers but weak actionability.",
        specificity: 4,
        proofScore: 4,
        riskScore: 2
      }),
      makeCard({
        promise: "The biggest " + topic + " mistakes " + audience + " should avoid",
        snippet: "Position the result around costly or annoying errors, then explain how to recognize and prevent each one.",
        proof: "Back each mistake with a plain example, consequence, warning sign, and safer alternative.",
        risk: "Avoid fearmongering. Keep claims proportional and name assumptions clearly.",
        notes: "Good for high-click intent, but risk control matters.",
        specificity: 4,
        proofScore: 3,
        riskScore: 3
      }),
      makeCard({
        promise: "How to decide whether " + topic + " is worth it for " + audience,
        snippet: "Help searchers compare tradeoffs instead of giving a one-size-fits-all answer.",
        proof: "Include a decision matrix, pros and cons, thresholds, and sample cases.",
        risk: "Avoid guaranteeing the right choice. Show the variables that change the answer.",
        notes: "Strong for nuanced topics where searchers need confidence.",
        specificity: 5,
        proofScore: 4,
        riskScore: 3
      }),
      makeCard({
        promise: topic + " explained simply, with examples for " + audience,
        snippet: "Make the page feel approachable while still giving enough detail to act intelligently.",
        proof: "Use definitions, before/after examples, short FAQs, and a glossary of confusing terms.",
        risk: "Avoid being too generic. Add audience-specific examples early.",
        notes: "Useful when the audience is anxious or early in the research journey.",
        specificity: 3,
        proofScore: 3,
        riskScore: 2
      }),
      makeCard({
        promise: "A proof-backed " + topic + " guide for " + audience,
        snippet: "Promise a more credible result by showing what the guidance is based on and where uncertainty remains.",
        proof: "Use citations, screenshots, expert review notes, data points, and clearly labeled assumptions.",
        risk: "Only use this if the article can actually support the proof promise.",
        notes: "Highest ceiling when competitors make unsupported claims.",
        specificity: 4,
        proofScore: 5,
        riskScore: 4
      })
    ];

    render();
    save();
    setStatus("Drafted 5 editable promise cards.");
  }

  function addBlank(){
    state.cards.unshift(makeCard({
      promise: "New search-result promise",
      snippet: "What the searcher will understand, decide, or do after clicking.",
      proof: "Examples, sources, screenshots, data, expert review, or visible process.",
      risk: "Claims that need qualification, narrowing, or removal.",
      notes: "",
      specificity: 3,
      proofScore: 3,
      riskScore: 3
    }));
    render();
    save();
  }

  function sortCards(){
    state.cards.sort(function(a,b){
      return score(b) - score(a);
    });
    render();
    save();
    setStatus("Sorted by score.");
  }

  function clearAll(){
    if(!confirm("Clear the board?")) return;
    state = { topic: "", audience: "", cards: [] };
    root.topic.value = "";
    root.audience.value = "";
    localStorage.removeItem(storeKey);
    render();
    setStatus("Cleared.");
  }

  function makeButton(text, className, action){
    const btn = createEl("button", {
      text: text,
      className: className || "",
      type: "button",
      dataset: { action: action }
    });
    return btn;
  }

  function makeField(labelText, field, card){
    const wrap = createEl("div");
    const label = createEl("label", { text: labelText });
    const textarea = createEl("textarea", {
      value: card[field] || "",
      dataset: { field: field }
    });

    textarea.addEventListener("input", function(){
      card[field] = textarea.value;
      save();
    });

    append(wrap, label, textarea);
    return wrap;
  }

  function makeSlider(labelText, field, card){
    const line = createEl("div", { className: "sliderline" });
    const name = createEl("span", { text: labelText });
    const slider = createEl("input", {
      type: "range",
      min: "1",
      max: "5",
      value: String(Number(card[field] || 1)),
      dataset: { field: field }
    });
    const out = createEl("output", { text: String(Number(card[field] || 1)) });

    slider.addEventListener("input", function(){
      card[field] = Number(slider.value);
      out.textContent = slider.value;
      updateCardScore(line.closest(".card"), card);
      updateTopCard();
      save();
    });

    append(line, name, slider, out);
    return line;
  }

  function updateCardScore(cardNode, card){
    if(!cardNode) return;
    const n = score(card);
    const scoreNode = cardNode.querySelector("[data-role='score']");
    const labelNode = cardNode.querySelector("[data-role='score-label']");
    if(scoreNode) scoreNode.textContent = String(n);
    if(labelNode) labelNode.textContent = scoreLabel(n);
  }

  function updateTopCard(){
    const ranked = state.cards.slice().sort(function(a,b){
      return score(b) - score(a);
    });
    const topId = ranked[0] ? ranked[0].id : "";

    document.querySelectorAll(".card").forEach(function(node){
      if(node.dataset.id === topId){
        node.classList.add("top");
      }else{
        node.classList.remove("top");
      }
    });
  }

  function makeScorePill(card){
    const pill = createEl("span", { className: "pill" });
    const n = score(card);
    const scoreSpan = createEl("span", {
      className: "score",
      text: String(n),
      dataset: { role: "score" }
    });
    const labelSpan = createEl("span", {
      text: scoreLabel(n),
      dataset: { role: "score-label" }
    });
    append(pill, scoreSpan, labelSpan);
    return pill;
  }

  function renderCard(card, index, topId){
    const article = createEl("article", {
      className: card.id === topId ? "card top" : "card",
      dataset: { id: card.id }
    });

    const meta = createEl("div", { className: "meta" });
    const left = createEl("div");
    const title = createEl("h2", { text: "Promise " + (index + 1) });
    append(left, title, makeScorePill(card));

    const tools = createEl("div", { className: "cardtools" });
    const copyBtn = makeButton("Copy", "small", "copyCard");
    const dupeBtn = makeButton("Duplicate", "small", "dupe");
    const deleteBtn = makeButton("Delete", "small warn", "delete");
    append(tools, copyBtn, dupeBtn, deleteBtn);
    append(meta, left, tools);

    copyBtn.addEventListener("click", function(){
      copyText(cardText(card));
    });

    dupeBtn.addEventListener("click", function(){
      const copy = makeCard(JSON.parse(JSON.stringify(card)));
      copy.id = uid();
      copy.promise = (copy.promise || "Untitled promise") + " copy";
      const idx = state.cards.findIndex(function(item){
        return item.id === card.id;
      });
      state.cards.splice(idx + 1, 0, copy);
      render();
      save();
    });

    deleteBtn.addEventListener("click", function(){
      state.cards = state.cards.filter(function(item){
        return item.id !== card.id;
      });
      render();
      save();
    });

    const fields = createEl("div", { className: "fields" });
    append(
      fields,
      makeField("Search-result promise", "promise", card),
      makeField("Snippet angle", "snippet", card),
      makeField("Proof needed", "proof", card),
      makeField("Risk / claim control", "risk", card),
      makeField("Notes", "notes", card)
    );

    const sliders = createEl("div", { className: "sliders" });
    append(
      sliders,
      makeSlider("Specificity", "specificity", card),
      makeSlider("Proof", "proofScore", card),
      makeSlider("Risk", "riskScore", card)
    );

    append(fields, sliders);
    append(article, meta, fields);
    return article;
  }

  function renderEmpty(){
    const empty = createEl("div", {
      className: "empty",
      text: "No cards yet. Add one or draft from your topic and audience."
    });
    root.cards.replaceChildren(empty);
  }

  function render(){
    if(!state.cards.length){
      renderEmpty();
      updateMetrics();
      buildBrief();
      return;
    }

    const ranked = state.cards.slice().sort(function(a,b){
      return score(b) - score(a);
    });
    const topId = ranked[0] ? ranked[0].id : "";

    const fragment = document.createDocumentFragment();
    state.cards.forEach(function(card, index){
      fragment.appendChild(renderCard(card, index, topId));
    });

    root.cards.replaceChildren(fragment);
    updateMetrics();
    buildBrief();
  }

  function updateMetrics(){
    const count = state.cards.length;
    root.countPill.textContent = count + " card" + (count === 1 ? "" : "s");

    const avg = count
      ? Math.round(state.cards.reduce(function(sum, card){
          return sum + score(card);
        }, 0) / count)
      : 0;

    root.avgPill.textContent = "Avg " + avg;
  }

  function cardText(card){
    return [
      "Promise: " + (card.promise || ""),
      "Score: " + score(card) + " (" + scoreLabel(score(card)) + ")",
      "Snippet angle: " + (card.snippet || ""),
      "Proof needed: " + (card.proof || ""),
      "Risk control: " + (card.risk || ""),
      "Notes: " + (card.notes || "")
    ].join("\n");
  }

  function buildBrief(){
    const topic = root.topic.value.trim() || "Not set";
    const audience = root.audience.value.trim() || "Not set";
    const ranked = state.cards.slice().sort(function(a,b){
      return score(b) - score(a);
    });
    const top = ranked[0];

    if(!ranked.length){
      root.brief.textContent = "Draft or add cards to generate a concise brief.";
      return root.brief.textContent;
    }

    const lines = [];
    lines.push("SEARCH PROMISE BRIEF");
    lines.push("");
    lines.push("Topic: " + topic);
    lines.push("Audience: " + audience);
    lines.push("");

    if(top){
      lines.push("Recommended lead promise");
      lines.push((top.promise || "Untitled promise") + " — Score " + score(top));
      lines.push("Snippet angle: " + (top.snippet || "Add snippet angle."));
      lines.push("Proof needed: " + (top.proof || "Add proof requirement."));
      lines.push("Risk control: " + (top.risk || "Add risk control."));
      lines.push("");
    }

    lines.push("Ranked promise options");
    ranked.forEach(function(card, index){
      lines.push((index + 1) + ". " + (card.promise || "Untitled promise") + " — " + score(card));
      if(card.notes){
        lines.push("   Note: " + card.notes);
      }
    });

    lines.push("");
    lines.push("Use this page to");
    lines.push("1. Match the promise to the real search intent.");
    lines.push("2. Add proof before making strong claims.");
    lines.push("3. Reduce or qualify high-risk wording.");
    lines.push("4. Turn the best promise into title, meta, intro, and outline.");

    const text = lines.join("\n");
    root.brief.textContent = text;
    return text;
  }

  async function copyText(text){
    try{
      await navigator.clipboard.writeText(text);
      setStatus("Copied.");
    }catch(err){
      const temp = createEl("textarea", { value: text });
      temp.setAttribute("readonly", "readonly");
      temp.style.position = "fixed";
      temp.style.left = "-9999px";
      document.body.appendChild(temp);
      temp.select();
      document.execCommand("copy");
      temp.remove();
      setStatus("Copied.");
    }
  }

  function exportTxt(){
    const text = buildBrief();
    const blob = new Blob([text], { type: "text/plain" });
    const link = createEl("a");
    const stamp = new Date().toISOString().slice(0,10);

    link.href = URL.createObjectURL(blob);
    link.download = "search-promise-brief-" + stamp + ".txt";
    document.body.appendChild(link);
    link.click();

    URL.revokeObjectURL(link.href);
    link.remove();
  }

  root.draftBtn.addEventListener("click", draftCards);
  root.addBtn.addEventListener("click", addBlank);
  root.sortBtn.addEventListener("click", sortCards);
  root.clearBtn.addEventListener("click", clearAll);
  root.copyBtn.addEventListener("click", function(){
    copyText(buildBrief());
  });
  root.exportBtn.addEventListener("click", exportTxt);

  root.topic.addEventListener("input", save);
  root.audience.addEventListener("input", save);

  load();
  render();
})();
</script>
</body>
</html>
